def has_duplicate(items):
    # O(n^2): compares every pair
    for i in range(len(items)):
        for j in range(i + 1, len(items)):
            if items[i] == items[j]:
                return True
    return False

def has_duplicate_fast(items):
    # O(n): one pass, remembering what we have seen
    seen = set()
    for x in items:
        if x in seen:
            return True
        seen.add(x)
    return False

def move_zeroes_to_end(a):
    w = 0                      # where the next non-zero goes
    for x in a:
        if x != 0:
            a[w] = x
            w += 1
    for i in range(w, len(a)):
        a[i] = 0
    return a

def missing_number(nums):          # values are 0..n with one missing
    n = len(nums)
    return n * (n + 1) // 2 - sum(nums)

def is_palindrome(s):
    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return False
        i, j = i + 1, j - 1
    return True

